auto func (auto value){  
    std::unordered_set<decltype(value)> uniqueElements;
    for (const auto& elem : value) {
        uniqueElements.insert(elem);
    }
    return std::make_pair(uniqueElements.size(), value.size());
}

auto func (auto value){ 
    std::unordered_set<decltype(value)> uniqueValues{value.begin(), value.end()};
    return std::make_pair(uniqueValues.size(), std::accumulate(value.begin(), value.end(), 0, [](int acc, const auto& val){ return acc + (val != val); }));
}

